/// Raven `ObjectDie`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:22-31`
pub fn ObjectDie(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
    meansOfDeath: c_int,
) {
    unsafe {
        if !(*self_).target.is_null() {
            G_UseTargets(ctx, self_, attacker);
        }

        // remove my script_targetname
        G_FreeEntity(ctx, self_);
    }
}

/// Raven `G_HeavyMelee`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:33-44`
pub fn G_HeavyMelee(ctx: GameContext<'_>, attacker: *mut gentity_t) -> qboolean {
    unsafe {
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && !attacker.is_null()
            && !(*attacker).client.is_null()
            && (*((*attacker).client as *mut gclient_t)).siegeClass != -1
            && ((*ctx.world).bg_state.bgSiegeClasses
                [(*((*attacker).client as *mut gclient_t)).siegeClass as usize]
                .classflags
                & (1 << CFL_HEAVYMELEE as c_int))
                != 0
        {
            return qtrue;
        }
        qfalse
    }
}

/// Raven `G_GetHitLocation`.
///
/// `ppoint` is read-only (the impact point is copied *from* it), so it stays
/// by-value (vec3 params only become `&mut` when written through).
/// Source: `oracle/oracle/codemp/game/g_combat.c:46-266`
pub fn G_GetHitLocation(ctx: GameContext<'_>, target: *mut gentity_t, ppoint: vec3_t) -> c_int {
    unsafe {
        let mut point: vec3_t = [0.0; 3];
        let mut point_dir: vec3_t = [0.0; 3];
        let mut forward: vec3_t = [0.0; 3];
        let mut right: vec3_t = [0.0; 3];
        let mut up: vec3_t = [0.0; 3];
        // §19: when `target->client` is NULL, C leaves `tangles` UNINITIALIZED
        // and feeds that garbage to AngleVectors below — UB; we zero-init it.
        let mut tangles: vec3_t = [0.0; 3];
        let mut tcenter: vec3_t = [0.0; 3];

        // Get target forward, right and up.
        if !(*target).client.is_null() {
            // Ignore player's pitch and roll.
            tangles = [0.0, (*target).r.currentAngles[YAW], 0.0];
        }

        AngleVectors(tangles, Some(&mut forward), Some(&mut right), Some(&mut up));

        // Get center of target.
        for i in 0..3 {
            tcenter[i] = ((*target).r.absmin[i] + (*target).r.absmax[i]) * 0.5;
        }

        // Get radius width of target (kept for parity; unused below like Raven).
        let _tradius = ((*target).r.maxs[0].abs()
            + (*target).r.maxs[1].abs()
            + (*target).r.mins[0].abs()
            + (*target).r.mins[1].abs())
            / 4.0;

        // Get impact point.
        if ppoint[0] != 0.0 || ppoint[1] != 0.0 || ppoint[2] != 0.0 {
            point = ppoint;
        } else {
            return HL_NONE;
        }

        for i in 0..3 {
            point_dir[i] = point[i] - tcenter[i];
        }
        VectorNormalize(&mut point_dir);

        let dot = |a: &vec3_t, b: &vec3_t| a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

        // Get bottom to top (vertical) position index.
        let udot = dot(&up, &point_dir);
        let vertical = if udot > 0.800 {
            4
        } else if udot > 0.400 {
            3
        } else if udot > -0.333 {
            2
        } else if udot > -0.666 {
            1
        } else {
            0
        };

        // Get back to front (forward) position index.
        let fdot = dot(&forward, &point_dir);
        let forward_idx = if fdot > 0.666 {
            4
        } else if fdot > 0.333 {
            3
        } else if fdot > -0.333 {
            2
        } else if fdot > -0.666 {
            1
        } else {
            0
        };

        // Get left to right (lateral) position index.
        let rdot = dot(&right, &point_dir);
        let lateral = if rdot > 0.666 {
            4
        } else if rdot > 0.333 {
            3
        } else if rdot > -0.333 {
            2
        } else if rdot > -0.666 {
            1
        } else {
            0
        };

        let hit_loc = vertical * 25 + forward_idx * 5 + lateral;

        if hit_loc <= 10 {
            // Feet.
            if rdot > 0.0 {
                HL_FOOT_RT
            } else {
                HL_FOOT_LT
            }
        } else if hit_loc <= 50 {
            // Legs.
            if rdot > 0.0 {
                HL_LEG_RT
            } else {
                HL_LEG_LT
            }
        } else if hit_loc == 56
            || hit_loc == 60
            || hit_loc == 61
            || hit_loc == 65
            || hit_loc == 66
            || hit_loc == 70
        {
            // Hands.
            if rdot > 0.0 {
                HL_HAND_RT
            } else {
                HL_HAND_LT
            }
        } else if hit_loc == 83
            || hit_loc == 87
            || hit_loc == 88
            || hit_loc == 92
            || hit_loc == 93
            || hit_loc == 97
        {
            // Arms.
            if rdot > 0.0 {
                HL_ARM_RT
            } else {
                HL_ARM_LT
            }
        } else if (107..=109).contains(&hit_loc)
            || (112..=114).contains(&hit_loc)
            || (117..=119).contains(&hit_loc)
        {
            // Head.
            HL_HEAD
        } else if udot < 0.3 {
            HL_WAIST
        } else if fdot < 0.0 {
            if rdot > 0.4 {
                HL_BACK_RT
            } else if rdot < -0.4 {
                HL_BACK_LT
            } else if fdot < 0.0 {
                HL_BACK
            } else {
                HL_NONE
            }
        } else if rdot > 0.3 {
            HL_CHEST_RT
        } else if rdot < -0.3 {
            HL_CHEST_LT
        } else if fdot < 0.0 {
            HL_CHEST
        } else {
            HL_NONE
        }
    }
}

/// Raven `ExplodeDeath`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:369-409`
pub fn ExplodeDeath(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        let mut forward: vec3_t = [0.0; 3];

        (*self_).takedamage = qfalse; // stop chain reaction runaway loops

        (*self_).s.loopSound = 0;
        (*self_).s.loopIsSoundset = qfalse;

        (*self_).s.pos.trBase = (*self_).r.currentOrigin;

        AngleVectors((*self_).s.angles, Some(&mut forward), None, None);

        if (*self_).splashDamage > 0 && (*self_).splashRadius > 0 {
            let mut attacker = self_;
            if !(*self_).parent.is_none() {
                attacker = &mut (*ctx.world).g_entities[(*self_).parent.unwrap().0 as usize]
                    as *mut gentity_t;
            }
            G_RadiusDamage(
                ctx,
                (*self_).r.currentOrigin,
                attacker,
                (*self_).splashDamage as f32,
                (*self_).splashRadius as f32,
                attacker,
                core::ptr::null_mut(),
                meansOfDeath_t::MOD_UNKNOWN as c_int,
            );
        }

        ObjectDie(ctx, self_, self_, self_, 20, 0);
    }
}

/// Raven `ScorePlum`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:417-427`
pub fn ScorePlum(ctx: GameContext<'_>, ent: *mut gentity_t, origin: vec3_t, score: c_int) {
    unsafe {
        let plum = G_TempEntity(ctx, origin, entity_event_t::EV_SCOREPLUM as c_int);
        // only send this temp entity to a single client
        (*plum).r.svFlags |= SVF_SINGLECLIENT;
        (*plum).r.singleClient = (*ent).s.number;
        //
        (*plum).s.otherEntityNum = (*ent).s.number;
        (*plum).s.time = score;
    }
}

/// Raven `AddScore`.
///
/// `origin` is unused by the compiled body (the `ScorePlum` call is commented
/// out), so it stays by-value.
/// Source: `oracle/oracle/codemp/game/g_combat.c:437-460`
pub fn AddScore(ctx: GameContext<'_>, ent: *mut gentity_t, origin: vec3_t, score: c_int) {
    unsafe {
        if (*ent).client.is_null() {
            return;
        }
        // no scoring during pre-match warmup
        if (*ctx.world).level.warmupTime != 0 {
            return;
        }
        let client = (*ent).client as *mut gclient_t;
        (*client).ps.persistant[persEnum_t::PERS_SCORE as usize] += score;
        if (*ctx.world).cvars.g_gametype.integer == GT_TEAM
            && (*ctx.world).globals.g_dontPenalizeTeam == 0
        {
            let team = (*client).ps.persistant[persEnum_t::PERS_TEAM as usize] as usize;
            (*ctx.world).level.teamScores[team] += score;
        }
        CalculateRanks(ctx);
    }
}

/// Raven `TossClientWeapon`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:469-559`
pub fn TossClientWeapon(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    direction: vec3_t,
    speed: f32,
) {
    unsafe {
        let mut vel: vec3_t = [0.0; 3];
        let client = (*self_).client as *mut gclient_t;
        let weapon = (*self_).s.weapon;

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            // no dropping weaps
            return;
        }

        if weapon <= WP_BRYAR_PISTOL as c_int {
            // can't have this
            return;
        }

        if weapon == WP_EMPLACED_GUN as c_int || weapon == WP_TURRET as c_int {
            return;
        }

        // find the item type for this weapon
        let item =
            crate::bg_misc::BG_FindItemForWeapon(core::mem::transmute::<c_int, weapon_t>(weapon));

        let mut ammoSub = (*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize]
            - bg_itemlist
                [crate::bg_misc::BG_GetItemIndexByTag(weapon, IT_WEAPON as c_int) as usize]
                .quantity;

        if ammoSub < 0 {
            let mut ammoQuan = (*item).quantity;
            ammoQuan -= -ammoSub;

            if ammoQuan <= 0 {
                // no ammo
                return;
            }
        }

        vel[0] = direction[0] * speed;
        vel[1] = direction[1] * speed;
        vel[2] = direction[2] * speed;

        let launched = crate::g_items::LaunchItem(ctx, item, (*client).ps.origin, vel);

        (*launched).s.generic1 = (*self_).s.number;
        (*launched).s.powerups = (*ctx.world).level.time + 1500;

        (*launched).count = bg_itemlist
            [crate::bg_misc::BG_GetItemIndexByTag(weapon, IT_WEAPON as c_int) as usize]
            .quantity;

        (*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize] -= bg_itemlist
            [crate::bg_misc::BG_GetItemIndexByTag(weapon, IT_WEAPON as c_int) as usize]
            .quantity;

        if (*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize] < 0 {
            (*launched).count -= -(*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize];
            (*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize] = 0;
        }

        if ((*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize] < 1
            && weapon != WP_DET_PACK as c_int)
            || (weapon != WP_THERMAL as c_int
                && weapon != WP_DET_PACK as c_int
                && weapon != WP_TRIP_MINE as c_int)
        {
            let mut i = 0;
            let mut weap = -1;

            (*client).ps.stats[statIndex_t::STAT_WEAPONS as usize] &= !(1 << weapon);

            while i < WP_NUM_WEAPONS as c_int {
                if ((*client).ps.stats[statIndex_t::STAT_WEAPONS as usize] & (1 << i)) != 0
                    && i != WP_NONE as c_int
                {
                    // this one's good
                    weap = i;
                    break;
                }
                i += 1;
            }

            if weap != -1 {
                (*self_).s.weapon = weap;
                (*client).ps.weapon = weap;
            } else {
                (*self_).s.weapon = 0;
                (*client).ps.weapon = 0;
            }

            G_AddEvent(self_, entity_event_t::EV_NOAMMO as c_int, weapon);
        }
    }
}

/// Raven `TossClientItems`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:568-635`
pub fn TossClientItems(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        let client = (*self_).client as *mut gclient_t;

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            // just don't drop anything then
            return;
        }

        // drop the weapon if not a gauntlet or machinegun
        let mut weapon = (*self_).s.weapon;

        // make a special check to see if they are changing to a new
        // weapon that isn't the mg or gauntlet.  Without this, a client
        // can pick up a weapon, be killed, and not drop the weapon because
        // their weapon change hasn't completed yet and they are still holding the MG.
        if weapon == WP_BRYAR_PISTOL as c_int {
            if (*client).ps.weaponstate == WEAPON_DROPPING as c_int {
                weapon = (*client).pers.cmd.weapon as c_int;
            }
            if ((*client).ps.stats[statIndex_t::STAT_WEAPONS as usize] & (1 << weapon)) == 0 {
                weapon = WP_NONE as c_int;
            }
        }

        (*self_).s.bolt2 = weapon;

        if weapon > WP_BRYAR_PISTOL as c_int
            && weapon != WP_EMPLACED_GUN as c_int
            && weapon != WP_TURRET as c_int
            && (*client).ps.ammo[weaponData[weapon as usize].ammoIndex as usize] != 0
        {
            // find the item type for this weapon
            let item = crate::bg_misc::BG_FindItemForWeapon(
                core::mem::transmute::<c_int, weapon_t>(weapon),
            );

            // tell all clients to remove the weapon model on this guy until he respawns
            let te = G_TempEntity(
                ctx,
                [0.0; 3],
                entity_event_t::EV_DESTROY_WEAPON_MODEL as c_int,
            );
            (*te).r.svFlags |= SVF_BROADCAST;
            (*te).s.eventParm = (*self_).s.number;

            // spawn the item
            crate::g_items::Drop_Item(ctx, self_, item, 0.0);
        }

        // drop all the powerups if not in teamplay
        if (*ctx.world).cvars.g_gametype.integer != GT_TEAM
            && (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
        {
            let mut angle: f32 = 45.0;
            for i in 1..PW_NUM_POWERUPS as c_int {
                if (*client).ps.powerups[i as usize] > (*ctx.world).level.time {
                    let item = crate::bg_misc::BG_FindItemForPowerup(core::mem::transmute::<
                        c_int,
                        powerup_t,
                    >(i));
                    if item.is_null() {
                        continue;
                    }
                    let drop = crate::g_items::Drop_Item(ctx, self_, item, angle);
                    // decide how many seconds it has left
                    (*drop).count =
                        ((*client).ps.powerups[i as usize] - (*ctx.world).level.time) / 1000;
                    if (*drop).count < 1 {
                        (*drop).count = 1;
                    }
                    angle += 45.0;
                }
            }
        }
    }
}

/// Raven `LookAtKiller`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:643-661`
pub fn LookAtKiller(self_: *mut gentity_t, inflictor: *mut gentity_t, attacker: *mut gentity_t) {
    unsafe {
        let mut dir: vec3_t = [0.0; 3];
        let mut angles: vec3_t = [0.0; 3];
        let client = (*self_).client as *mut gclient_t;

        if !attacker.is_null() && attacker != self_ {
            let a = (*attacker).s.pos.trBase;
            let s = (*self_).s.pos.trBase;
            dir = [a[0] - s[0], a[1] - s[1], a[2] - s[2]];
        } else if !inflictor.is_null() && inflictor != self_ {
            let inf = (*inflictor).s.pos.trBase;
            let s = (*self_).s.pos.trBase;
            dir = [inf[0] - s[0], inf[1] - s[1], inf[2] - s[2]];
        } else {
            (*client).ps.stats[statIndex_t::STAT_DEAD_YAW as usize] =
                (*self_).s.angles[YAW] as c_int;
            return;
        }

        (*client).ps.stats[statIndex_t::STAT_DEAD_YAW as usize] = vectoyaw(dir) as c_int;

        // Raven computes `angles` here but never consumes it; kept faithfully.
        angles[YAW] = vectoyaw(dir);
        angles[PITCH] = 0.0;
        angles[ROLL] = 0.0;
    }
}

/// Raven `GibEntity`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:668-673`
pub fn GibEntity(ctx: GameContext<'_>, self_: *mut gentity_t, killer: c_int) {
    unsafe {
        G_AddEvent(self_, entity_event_t::EV_GIB_PLAYER as c_int, killer);
        (*self_).takedamage = qfalse;
        (*self_).s.eType = entityType_t::ET_INVISIBLE as c_int;
        (*self_).r.contents = 0;
    }
}

